import assert from 'node:assert/strict';
import {mkdirSync,writeFileSync,readFileSync} from 'node:fs';
import {chromium,webkit} from 'playwright';
import {displayedChapterCollections,chapterHash} from '../lib/practice-chapters.ts';
const online=Boolean(process.env.KLINK_TEST_ONLINE);
const base=process.env.KLINK_TEST_BASE||'http://127.0.0.1:18996',out=process.env.KLINK_TEST_OUTPUT||'outputs/writing-keyboard-next-20261101/local';mkdirSync(out,{recursive:true});
const activities=['write-letter','copy','write','dictation','paper-dictation','sentence-dictation','functional-message','functional-form'];
const inventory=activities.map(activity=>({activity,rows:['practice','guided'].flatMap(help=>['alfa-a','alfa-b','alfa-c','a1','a2','b1'].flatMap(level=>displayedChapterCollections(activity,{level,help}).filter(row=>row.exercises.length).map(row=>({activity,help,level,row}))))}));
const reading=level=>displayedChapterCollections('text-question',{level,help:'practice'}).map(row=>({...row,exercises:row.contentUrl?JSON.parse(readFileSync('public'+row.contentUrl)).exercises:row.exercises})).find(r=>r.exercises.length>1);
const cases=inventory.map(({rows})=>rows[0]);assert(cases.every(Boolean));const checks=[],audioNext=[],native=[],errors=[];
function instrument(){const v=new EventTarget();v.height=innerHeight;v.offsetTop=0;Object.defineProperty(window,'visualViewport',{configurable:true,value:v});window.setTestKeyboard=(height,top=0)=>{v.height=height;v.offsetTop=top;v.dispatchEvent(new Event('resize'));v.dispatchEvent(new Event('scroll'));};if(!localStorage.getItem('klink.taalroute.attempts.v1'))localStorage.setItem('klink.taalroute.attempts.v1','[{"existing":true}]');window.played=[];window.ended=[];window.pauses=0;window.addEventListener('klink-audio-source',e=>{const a=e.detail;a.volume=0;window.audio=a;window.played.push(a.src);if(!a.observed){a.observed=true;a.addEventListener('ended',()=>window.ended.push(a.src));}});}
function fakeAudio(){window.Audio=class extends EventTarget{play(){this.paused=false;if(!window.holdAudio)this.timer=setTimeout(()=>{this.paused=true;this.dispatchEvent(new Event('ended'));},5);return Promise.resolve();}pause(){this.paused=true;window.pauses++;clearTimeout(this.timer);}};}
const route=c=>'/'+chapterHash({chapter:'writing',activity:c.activity,collection:c.row.id,level:c.level,help:c.help});
async function measure(p){await p.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));return p.evaluate(()=>{const main=document.querySelector('.learner-main'),v=window.visualViewport;const visible=e=>{const r=e.getBoundingClientRect();let clip={left:0,right:innerWidth,top:v.offsetTop,bottom:v.offsetTop+v.height};for(let a=e.parentElement;a;a=a.parentElement){if(/auto|scroll|hidden|clip/.test(getComputedStyle(a).overflow)){const q=a.getBoundingClientRect();clip={left:Math.max(clip.left,q.left),right:Math.min(clip.right,q.right),top:Math.max(clip.top,q.top),bottom:Math.min(clip.bottom,q.bottom)};}}return r.width>=44&&r.height>=44&&r.left>=clip.left-1&&r.right<=clip.right+1&&r.top>=clip.top-1&&r.bottom<=clip.bottom+1;};return{keyboardOpen:main.dataset.keyboardOpen==='true',answerReachable:visible(main.querySelector('.cp-text-entry input,.cp-text-entry textarea')),checkReachable:visible(main.querySelector('[data-practice-check]')),nextReachable:visible(main.querySelector('[data-practice-next]')),noHorizontalScroll:document.documentElement.scrollWidth<=innerWidth+1,progressPreserved:JSON.parse(localStorage.getItem('klink.taalroute.attempts.v1')).some(a=>a.existing),inputFont:Number.parseFloat(getComputedStyle(main.querySelector('.cp-text-entry input,.cp-text-entry textarea')).fontSize)};});}
for(const[engine,type]of Object.entries({chromium,webkit})){const browser=await type.launch();try{
 for(const c of cases)for(const[width,height,visible]of(online?[[320,568,230]]:[[320,568,230],[740,390,210]]))for(const model of(online?['visual-only']:['visual-only','resizes-content']))for(const colorScheme of(online?['light']:['light','dark'])){
  const p=await browser.newPage({viewport:{width,height},hasTouch:true,colorScheme});p.on('pageerror',e=>errors.push(e.message));await p.addInitScript(instrument);await p.addInitScript(fakeAudio);await p.goto(base+route(c));const field=p.locator('.cp-text-entry input,.cp-text-entry textarea');await field.waitFor();await p.waitForFunction(()=>!document.querySelector('.cp-text-entry input,.cp-text-entry textarea').disabled);const value=c.row.exercises[0].fields?.flatMap(f=>f.acceptedAnswers||[])[0]||String(c.row.exercises[0].target||'Mijn eigen bericht.');await field.fill(value);if(model==='resizes-content')await p.setViewportSize({width,height:visible});await p.evaluate(([h,t])=>window.setTestKeyboard(h,t),[visible,model==='visual-only'?20:0]);
  const m=await measure(p);for(const k of['keyboardOpen','answerReachable','checkReachable','nextReachable','noHorizontalScroll','progressPreserved'])assert(m[k],engine+' '+c.activity+' '+width+' '+model+' '+k+' '+JSON.stringify(m));assert(m.inputFont>=16);checks.push({engine,activity:c.activity,width,height,visible,model,colorScheme,...m});
  if(engine==='chromium'&&width===320&&model==='visual-only'&&colorScheme==='light')await p.screenshot({path:out+'/'+c.activity+'-keyboard.png'});
  if(c.activity.startsWith('functional-')){await field.press('Enter');assert((await field.inputValue()).includes('\n'),'textarea keeps native newline');if(c.activity==='functional-form'){await p.evaluate(()=>window.setTestKeyboard(innerHeight,0));if(model==='resizes-content')await p.setViewportSize({width,height});await p.locator('.cp-sender-choice button').first().click();}await p.getByRole('button',{name:'Kijk na',exact:true}).click();for(const box of await p.locator('.cp-writing-check input').all())await box.check();await p.locator('.cp-writing-check').getByRole('button',{name:'Klaar',exact:true}).click();assert(await p.locator('[data-practice-next]').isEnabled());}
  if(model==='resizes-content')await p.setViewportSize({width,height});await p.evaluate(h=>window.setTestKeyboard(h,0),height);await p.goto(base+'/#learner/home');await p.locator('.cp-home').waitFor();assert(await p.locator('.learner-nav').isVisible());assert(await p.locator('.taalroute-header').isVisible());await p.close();
 }console.log(engine,online?'8 writing keyboard layouts PASS':'64 writing keyboard layouts PASS');
 for(const level of['a1','b1'])for(const method of['tap','Enter','ArrowRight']){
  const row=reading(level),e=row.exercises[0];assert(row);const p=await browser.newPage({viewport:{width:390,height:844},hasTouch:true});p.on('pageerror',e=>errors.push(e.message));await p.addInitScript(instrument);await p.addInitScript(fakeAudio);await p.goto(base+'/'+chapterHash({chapter:'texts',activity:'text-question',collection:row.id,level,help:'practice'}));await p.locator('.cp-choice-grid').waitFor();await p.waitForTimeout(80);const root=p.locator('[data-exercise-id]'),id=await root.getAttribute('data-exercise-id');await p.evaluate(()=>{window.holdAudio=true;});await p.locator('[data-practice-listen]').click();await p.waitForFunction(()=>window.audio&&!window.audio.paused);assert(await p.locator('[data-practice-next]').isDisabled());const choices=p.locator('.cp-extended-option>button:first-child'),right=e.options.findIndex(o=>e.answer.correctOptionIds.includes(o.id)),wrong=e.options.findIndex(o=>!e.answer.correctOptionIds.includes(o.id));await choices.nth(wrong).click();assert(await p.locator('[data-practice-next]').isDisabled());await choices.nth(right).click();assert(await p.locator('[data-practice-next]').isEnabled());assert(await p.evaluate(()=>!window.audio.paused));
  // A confirmed answer never permits leaving an active microphone/recording.
  await root.evaluate(el=>{const marker=document.createElement('div');marker.dataset.practiceRecording='true';marker.id='recording-test';el.append(marker);});await p.locator('[data-practice-next]').click();assert.equal(await root.getAttribute('data-exercise-id'),id);await root.locator('h3').focus();await p.keyboard.press('ArrowRight');assert.equal(await root.getAttribute('data-exercise-id'),id);await p.locator('#recording-test').evaluate(el=>el.remove());const pauses=await p.evaluate(()=>window.pauses);if(method==='tap')await p.locator('[data-practice-next]').click();else{await root.locator('h3').focus();await p.keyboard.press(method);}await p.waitForFunction(id=>document.querySelector('[data-exercise-id]')?.dataset.exerciseId!==id,id);assert(await p.evaluate(n=>window.pauses>n,pauses));await p.waitForTimeout(100);assert.equal(await p.locator('.cp-audio-retry').count(),0);assert(!await p.locator('[data-practice-ready="true"]').count());assert(await p.evaluate(()=>JSON.parse(localStorage.getItem('klink.taalroute.attempts.v1')).some(a=>a.existing)));audioNext.push({engine,level,method,correctAnswerAdvancesWhileAudio:true,oldAudioStopped:true,unansweredAndWrongBlocked:true,recordingProtected:true,noStaleFeedback:true,progressPreserved:true});await p.close();
 }console.log(engine,'audio-next safety PASS');
 const row=reading('a1'),e=row.exercises[0];const p=await browser.newPage({viewport:{width:390,height:844},hasTouch:true});await p.addInitScript(instrument);p.on('pageerror',e=>errors.push(e.message));await p.goto(base+'/'+chapterHash({chapter:'texts',activity:'text-question',collection:row.id,level:'a1',help:'practice'}));await p.locator('.cp-choice-grid').waitFor();await p.locator('[data-practice-listen]').click();await p.waitForFunction(()=>window.audio&&!window.audio.paused&&window.audio.currentTime>0);const id=await p.locator('[data-exercise-id]').getAttribute('data-exercise-id');await p.locator('.cp-extended-option>button:first-child').nth(e.options.findIndex(o=>e.answer.correctOptionIds.includes(o.id))).click();assert(await p.evaluate(()=>!window.audio.paused));await p.locator('[data-practice-next]').tap();await p.waitForFunction(id=>document.querySelector('[data-exercise-id]')?.dataset.exerciseId!==id,id);assert(await p.evaluate(()=>window.audio.paused));const stored=await p.evaluate(()=>Object.fromEntries(Object.entries(localStorage).filter(([k])=>k.includes('attempt')||k.startsWith('klink.group.'))));await p.reload();await p.locator('[data-exercise-id]').waitFor();for(const[k,v]of Object.entries(stored))assert.deepEqual(JSON.parse(await p.evaluate(k=>localStorage.getItem(k),k)),JSON.parse(v));native.push({engine,nativeAudio:true,advanceDuringPlayback:true,oldAudioStopped:true,progressSurvivesReload:true});await p.close();
 }finally{await browser.close();writeFileSync(out+'/checks.json',JSON.stringify({base,inventory:inventory.map(i=>({activity:i.activity,collections:i.rows.length})),checks,audioNext,native,errors,nativeScreenKeyboardTested:false,method:'Real controls with simulated VisualViewport/viewport keyboard in two engines; native audio for next-during-playback.'},null,2)+'\n');}}
assert.equal(checks.length,online?16:128);assert.equal(audioNext.length,12);assert.equal(native.length,2);assert.deepEqual(errors,[]);console.log('PASS',checks.length,'keyboard layouts, 12 audio-next safety trials, 2 real audio/progress trials');
